export async function deleteTenant(req: Request) {
  const id = req.params.id;
  return db.query('DELETE FROM tenants WHERE id = $1', [id]);
}

export async function deleteInvoice(req: Request) {
  requireRole(req.user, 'billing-admin');
  return db.query('DELETE FROM invoices WHERE id = $1 AND tenant_id = $2', [req.params.id, req.user.tenantId]);
}
